// Pagefind's index is only generated by `astro build`, so search shows a notice in dev.
import { useEffect, useRef, useState } from 'react';
import Icon from './Icon.jsx';

const BUNDLE = '/pagefind/pagefind.js';
const MAX_PAGES = 8;
const MAX_SECTIONS = 3;

let pagefindPromise;
function loadPagefind() {
	if (!pagefindPromise) {
		pagefindPromise = import(/* @vite-ignore */ BUNDLE).then(async (pagefind) => {
			await pagefind.options({ baseUrl: '/' });
			pagefind.init();
			return pagefind;
		});
		// Forget a failed load so the next search tries again.
		pagefindPromise.catch(() => {
			pagefindPromise = undefined;
		});
	}
	return pagefindPromise;
}

async function runSearch(pagefind, query) {
	const search = await pagefind.debouncedSearch(query, {}, 150);
	if (!search) return null;
	const pages = await Promise.all(search.results.slice(0, MAX_PAGES).map((result) => result.data()));
	return pages.flatMap((page) => {
		const title = page.meta?.title ?? page.url;
		const sections = (page.sub_results ?? [])
			.filter((sub) => sub.url !== page.url && sub.title !== title)
			.slice(0, MAX_SECTIONS)
			.map((sub) => ({ kind: 'section', url: sub.url, title: sub.title, excerpt: sub.excerpt }));
		return [{ kind: 'page', url: page.url, title, excerpt: page.excerpt }, ...sections];
	});
}

export default function SearchDialog() {
	const dialogRef = useRef(null);
	const inputRef = useRef(null);
	const listRef = useRef(null);
	const [open, setOpen] = useState(false);
	const [query, setQuery] = useState('');
	const [items, setItems] = useState([]);
	const [itemsQuery, setItemsQuery] = useState('');
	const [status, setStatus] = useState('idle');
	const [activeIndex, setActiveIndex] = useState(0);
	const [shortcut, setShortcut] = useState('Ctrl K');

	useEffect(() => {
		if (/Mac|iPhone|iPad/.test(navigator.userAgent)) setShortcut('⌘K');
		const onKey = (event) => {
			const typing =
				event.target instanceof HTMLElement && event.target.closest('input, textarea, select, [contenteditable="true"]');
			if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
				event.preventDefault();
				setOpen((value) => !value);
			} else if (event.key === '/' && !typing) {
				event.preventDefault();
				setOpen(true);
			}
		};
		window.addEventListener('keydown', onKey);
		return () => window.removeEventListener('keydown', onKey);
	}, []);

	useEffect(() => {
		const dialog = dialogRef.current;
		if (!dialog) return;
		if (open && !dialog.open) {
			dialog.showModal();
			inputRef.current?.focus();
			inputRef.current?.select();
			loadPagefind().catch(() => setStatus('unavailable'));
		} else if (!open && dialog.open) {
			dialog.close();
		}
		document.documentElement.toggleAttribute('data-search-open', open);
	}, [open]);

	useEffect(() => {
		const text = query.trim();
		if (!text) {
			setItems([]);
			setStatus((current) => (current === 'unavailable' ? current : 'idle'));
			return;
		}
		let cancelled = false;
		setStatus('loading');
		loadPagefind()
			.then((pagefind) => runSearch(pagefind, text))
			.then((found) => {
				if (cancelled || found === null) return;
				setItems(found);
				setItemsQuery(text);
				setActiveIndex(0);
				setStatus(found.length ? 'ready' : 'empty');
			})
			.catch(() => !cancelled && setStatus('unavailable'));
		return () => {
			cancelled = true;
		};
	}, [query]);

	useEffect(() => {
		listRef.current?.querySelector('[data-active="true"]')?.scrollIntoView({ block: 'nearest' });
	}, [activeIndex]);

	const onInputKey = (event) => {
		// The previous query's results stay up while the next one loads, so Enter can't open one of those.
		if (!items.length || itemsQuery !== query.trim()) return;
		if (event.key === 'ArrowDown') {
			event.preventDefault();
			setActiveIndex((index) => (index + 1) % items.length);
		} else if (event.key === 'ArrowUp') {
			event.preventDefault();
			setActiveIndex((index) => (index - 1 + items.length) % items.length);
		} else if (event.key === 'Enter') {
			event.preventDefault();
			window.location.href = items[activeIndex].url;
			setOpen(false);
		}
	};

	return (
		<>
			<button type="button" className="docs-search-trigger" onClick={() => setOpen(true)} aria-label="Search the docs">
				<Icon name="magnifier" />
				<span className="docs-search-trigger-label">Search</span>
				<kbd className="docs-search-trigger-kbd">{shortcut}</kbd>
			</button>
			<dialog
				ref={dialogRef}
				className="docs-search"
				aria-label="Search the docs"
				onClose={() => setOpen(false)}
				onClick={(event) => event.target === dialogRef.current && setOpen(false)}
			>
				<div className="docs-search-panel">
					<div className="docs-search-field">
						<Icon name="magnifier" />
						<input
							ref={inputRef}
							type="search"
							placeholder="Search the docs"
							aria-label="Search the docs"
							aria-controls="docs-search-results"
							aria-activedescendant={items.length ? `docs-search-item-${activeIndex}` : undefined}
							autoComplete="off"
							spellCheck="false"
							value={query}
							onChange={(event) => setQuery(event.target.value)}
							onKeyDown={onInputKey}
						/>
						<button type="button" className="docs-search-close" onClick={() => setOpen(false)}>
							Esc
						</button>
					</div>
					<div className="docs-search-body">
						{status === 'unavailable' && (
							<p className="docs-search-note">Search is only available in production builds.</p>
						)}
						{status === 'idle' && <p className="docs-search-note">Search guides, tweaks, features, and FAQs.</p>}
						{status === 'empty' && <p className="docs-search-note">No results for "{query.trim()}".</p>}
						{items.length > 0 && status !== 'unavailable' && (
							<ul id="docs-search-results" className="docs-search-results" role="listbox" ref={listRef}>
								{items.map((item, index) => (
									<li
										key={`${item.url}-${index}`}
										role="option"
										id={`docs-search-item-${index}`}
										aria-selected={index === activeIndex}
									>
										<a
											href={item.url}
											className={`docs-search-result docs-search-result--${item.kind}`}
											data-active={index === activeIndex}
											onMouseMove={() => setActiveIndex(index)}
											onClick={() => setOpen(false)}
										>
											<Icon
												name={item.kind === 'page' ? 'document' : 'right-caret'}
												className="docs-search-result-icon"
											/>
											<span className="docs-search-result-text">
												<span className="docs-search-result-title">{item.title}</span>
												<span
													className="docs-search-result-excerpt"
													dangerouslySetInnerHTML={{ __html: item.excerpt }}
												/>
											</span>
										</a>
									</li>
								))}
							</ul>
						)}
					</div>
					<div className="docs-search-footer" aria-hidden="true">
						<span>
							<kbd>↑</kbd>
							<kbd>↓</kbd> to navigate
						</span>
						<span>
							<kbd>↵</kbd> to open
						</span>
						<span>
							<kbd>Esc</kbd> to close
						</span>
					</div>
				</div>
			</dialog>
		</>
	);
}
